import{_ as s,o as n,c as o,a2 as r}from"./chunks/framework.Zh78JZbW.js";const t="/kodus-releases/screenshots/partager.png",a="/kodus-releases/screenshots/rejoindre.png",v=JSON.parse('{"title":"Jouer ensemble","description":"","frontmatter":{},"headers":[],"relativePath":"guide/jouer-ensemble.md","filePath":"guide/jouer-ensemble.md"}'),i={name:"guide/jouer-ensemble.md"};function l(u,e,c,d,m,p){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="jouer-ensemble" tabindex="-1">Jouer ensemble <a class="header-anchor" href="#jouer-ensemble" aria-label="Permalink to &quot;Jouer ensemble&quot;">​</a></h1><p><strong>Jouer ensemble</strong> permet de jouer avec vos amis par Internet, <strong>sans serveur</strong> : l&#39;un ouvre son monde solo, les autres le rejoignent en un clic depuis Kodus. Kodus s&#39;occupe aussi des mods : il partage votre instance avec vos amis et la garde synchronisée.</p><h2 id="partager-une-instance" tabindex="-1">Partager une instance <a class="header-anchor" href="#partager-une-instance" aria-label="Permalink to &quot;Partager une instance&quot;">​</a></h2><p>Sur la page d&#39;une instance, cliquez sur <strong>Partager</strong>, puis activez <strong>Partager avec mes amis</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Dès la création</p><p>Dans <strong>Nouvelle instance</strong> et sur la page <strong>Jouer avec un mod</strong>, les cases <strong>Partager avec mes amis</strong> et <strong>Héberger des parties sans serveur</strong> activent tout de suite le partage et l&#39;hébergement de l&#39;instance créée. Kodus retient votre choix pour la prochaine fois.</p></div><p><img src="'+t+'" alt="Fenêtre Partager : code de partage, réglages des mods et liste des contenus partagés"></p><ul><li>Vos amis voient l&#39;instance sous votre nom, dans le panneau Amis de l&#39;accueil.</li><li>Un <strong>code de partage</strong> (ex. <code>K7P-4QX</code>) permet aussi à un joueur Kodus qui n&#39;est pas votre ami de l&#39;installer. Le code ne permet pas de rejoindre vos parties.</li><li><strong>Partager aussi mes réglages de mods</strong> envoie les fichiers du dossier <code>config</code> : vos amis choisissent ensuite de les prendre ou non.</li><li>Quand vous ajoutez, retirez ou mettez à jour un mod, le partage se met à jour tout seul.</li></ul><p>Les mods marqués <strong>requis pour rejoindre</strong> sont les mods de contenu (nouveaux blocs, mobs…) : vos amis doivent les avoir pour entrer dans votre monde. Les mods visuels ou d&#39;optimisation, comme Sodium, peuvent être différents chez chacun.</p><div class="info custom-block"><p class="custom-block-title">Ce qui n&#39;est jamais partagé</p><p>Vos mondes, vos paramètres du jeu (touches, vidéo…) et les mods ajoutés à la main. Pour ces derniers, vos amis voient seulement leur nom, pour pouvoir vous les demander.</p></div><h2 id="installer-l-instance-d-un-ami" tabindex="-1">Installer l&#39;instance d&#39;un ami <a class="header-anchor" href="#installer-l-instance-d-un-ami" aria-label="Permalink to &quot;Installer l&#39;instance d&#39;un ami&quot;">​</a></h2><ul><li>Depuis l&#39;accueil : cliquez sur l&#39;étiquette 📦 sous le nom de votre ami. Depuis la page <strong>Amis</strong> : bouton <strong>Installer</strong>.</li><li>Avec un code : <strong>Nouvelle instance</strong> → <strong>Installer l&#39;instance d&#39;un ami avec un code de partage…</strong></li></ul><p>La fenêtre demande <strong>Où l&#39;installer ?</strong> :</p><ul><li><strong>Nouvelle instance</strong> : une copie complète de son instance, liée (voir Synchroniser) ;</li><li><strong>Dans une de vos instances</strong> de même version et même loader : Kodus n&#39;y ajoute que ses <strong>mods requis</strong>, le reste de votre instance ne change pas.</li></ul><p>Les contenus <strong>optionnels</strong> (mods visuels ou d&#39;optimisation, packs de ressources, shaders) ne sont pas nécessaires pour jouer ensemble : cochez ceux que vous voulez. Ils sont tous cochés pour une nouvelle instance, aucun pour une de vos instances. Ceux que vous avez décochés ne sont jamais réinstallés par <strong>Synchroniser</strong>.</p><p>Kodus installe exactement les mêmes versions des mods que votre ami. Cochez <strong>Prendre aussi les réglages de mods</strong> si vous voulez sa configuration.</p><h2 id="synchroniser" tabindex="-1">Synchroniser <a class="header-anchor" href="#synchroniser" aria-label="Permalink to &quot;Synchroniser&quot;">​</a></h2><p>L&#39;instance installée reste liée à celle de votre ami. Quand il change ses mods, un point apparaît à côté de l&#39;instance et sa page affiche <strong>Nouveautés dans l&#39;instance de…</strong> : cliquez sur <strong>Synchroniser</strong>.</p><p>Kodus montre d&#39;abord ce qui change (ajouté, mis à jour, retiré). Les mods que vous avez ajoutés vous-même ne sont jamais retirés, et vos mondes sont conservés.</p><p><strong>Délier</strong> transforme la copie en instance ordinaire : elle ne propose plus de synchroniser.</p><h2 id="heberger-une-partie" tabindex="-1">Héberger une partie <a class="header-anchor" href="#heberger-une-partie" aria-label="Permalink to &quot;Héberger une partie&quot;">​</a></h2><ol><li>Dans la fenêtre <strong>Partager</strong> de votre instance, activez <strong>Jouer ensemble sans serveur</strong>. Kodus installe les mods <a href="https://modrinth.com/mod/e4mc" target="_blank" rel="noreferrer">e4mc</a> (l&#39;adresse publique) et <a href="https://modrinth.com/mod/mcwifipnp" target="_blank" rel="noreferrer">LAN World Plug-n-Play</a> (l&#39;accès des joueurs Kodus). Une instance Vanilla doit passer en Fabric : rien ne change en jeu et vos mondes sont conservés.</li><li>Lancez le jeu et ouvrez un monde.</li><li>Échap → <strong>Ouvrir au réseau local</strong> : l&#39;écran de LAN World Plug-n-Play s&#39;affiche, déjà réglé par Kodus. Cliquez sur le bouton pour démarrer.</li></ol><p>Kodus affiche <strong>Ta partie est ouverte à tes amis</strong> sur l&#39;accueil, avec l&#39;adresse de la partie, et prévient vos amis. La partie se ferme quand vous quittez le monde.</p><div class="warning custom-block"><p class="custom-block-title">Online Mode</p><p>Kodus règle <strong>Online Mode</strong> sur <strong>Désactivé</strong> pour que les joueurs Kodus puissent entrer. Si l&#39;accueil indique que <strong>Online Mode est activé</strong>, quittez le monde, rouvrez-le, puis <strong>Ouvrir au réseau local</strong> en remettant <strong>Online Mode</strong> sur <strong>Désactivé</strong>.</p></div><div class="tip custom-block"><p class="custom-block-title">Visibilité</p><p>Vos amis voient votre partie même avec la visibilité « En ligne seulement ». En visibilité <strong>Invisible</strong>, ils ne la voient pas : donnez-leur l&#39;adresse (bouton <strong>Copier</strong>).</p></div><h2 id="rejoindre-un-ami" tabindex="-1">Rejoindre un ami <a class="header-anchor" href="#rejoindre-un-ami" aria-label="Permalink to &quot;Rejoindre un ami&quot;">​</a></h2><p>Quand un ami ouvre une partie, Kodus vous prévient et un bouton <strong>Rejoindre</strong> apparaît sous son nom.</p><p><img src="'+a+'" alt="Panneau Amis : partie ouverte avec le bouton Rejoindre, puis choix de l&#39;instance"></p><p>Kodus vous montre les mods requis et vos instances de la même version :</p><ul><li><strong>prête</strong> : cliquez sur <strong>Rejoindre</strong>, le jeu se lance directement connecté à la partie ;</li><li><strong>il manque un mod</strong> ou <strong>version différente</strong> : <strong>Compléter et rejoindre</strong> ajoute les mods de contenu de votre ami à cette instance, aux mêmes versions, sans toucher au reste ;</li><li><strong>Créer une copie de son instance</strong> installe son instance (liée), puis lance le jeu ;</li><li><strong>Rejoindre quand même</strong> essaie avec l&#39;instance choisie telle quelle.</li></ul><p>Si votre ami n&#39;a aucun mod de contenu, n&#39;importe quelle instance de la même version convient, même Vanilla.</p><p>Si la connexion est refusée (un mod manque), Kodus propose <strong>Voir les choix</strong> pour compléter votre instance ou installer celle de votre ami.</p><h2 id="bon-a-savoir" tabindex="-1">Bon à savoir <a class="header-anchor" href="#bon-a-savoir" aria-label="Permalink to &quot;Bon à savoir&quot;">​</a></h2><ul><li>Le relais qui fait passer la partie par Internet est fourni gratuitement par l&#39;autrice d&#39;e4mc, pas par Kodus : s&#39;il est lent ou indisponible, réessayez plus tard. Aucun port n&#39;est ouvert sur votre box et votre adresse IP n&#39;est pas montrée.</li><li>Toute personne qui connaît l&#39;adresse peut entrer tant que le monde est ouvert. Kodus ne la montre qu&#39;à vos amis ; les commandes <code>/ban</code> et <code>/whitelist</code> permettent de filtrer.</li></ul><div class="danger custom-block"><p class="custom-block-title">e4all</p><p>Les premières versions de Jouer ensemble utilisaient le mod e4all. Il a été supprimé de Modrinth et signalé comme dangereux : Kodus le retire automatiquement de vos instances. Si vous l&#39;avez installé ailleurs (autre launcher), supprimez-le et lancez une analyse antivirus.</p></div><ul><li>Pour le Goupil SMP ou un serveur, voir <a href="./jouer">Jouer en multijoueur</a>.</li></ul>',35)])])}const h=s(i,[["render",l]]);export{v as __pageData,h as default};
